// TH16 v1.00a approved aliases of identical TH18 type slots (2026-11-07).
// Only the types used by this card are copied from transcribe/th16/touhou-bullets.ecl.
// source etSprite(0,34,6) / etSprite(0,4,6) -> TH16 type 34 (DROPLET); valid colors 0-15.
const TH16_DROPLET: int = 896;

// TH16 v1.00a Extra 关底 BossCard8（SPELL_ID 116「秘儀「無縁の芸能者」」）
// 源: st07bs.ecl.txt:1867-1922；依赖 BossCard8_at 1995-2019、BossCard8_at2 2021-2032、
//     BossCard8_ECir00 1940-1960；入口位置取 Boss:10-111 的 movePos(0,128)。
// 源帧 0 为 boss_pattern 首帧，外壳缓冲 OPENING_BUFFER 在其之前。

const TIME_LIMIT: int = 5524;                       // 120缓冲 + 5400源窗口 + 4启动余量
const OPENING_BUFFER: int = 120;
const PHASE_FRAMES: int = TIME_LIMIT - OPENING_BUFFER - 4; // 源 spellEx/setInterrupt 的 5400
const SPELL_CARD8: int = 116;

// 源 VELTIME 120 帧把标量速 0.01 拉到 2.0：delta=(2.0-0.01)/120 px/帧^2
const RISE_ACCEL: fx = 0.01658fx;

xformdef RISE_RAMP {
    // 源 etEx WAIT(180) 后接 VELTIME(a=120, r=2.0, s 保角)；沿弹自身方向加速
    wait(180);
    set_gravity(at_effect(RISE_ACCEL * cos($self_angle)),
                at_effect(RISE_ACCEL * sin($self_angle)));
    wait(120);
    set_gravity(0fx, 0fx);
}

// 源 BossCard8_at：etAim(0,1) 固定方向扇形，4路1层，弹型34色6，
// 每15帧一波；基准 -pi/2 + RANDF2*5deg，路间距 30deg；etOffset(0,48)、etDist(32)。
async sub wave_emitter() {
    sh_reset(0);
    sh_sprite(0, TH16_DROPLET, 6);
    sh_ring(0, 0);
    sh_aim(0, 0);
    sh_count(0, 4, 1);
    sh_speed(0, 0.01fx, 0fx);            // etSpeed(0,0.01,1.0)，M=1只取首值
    sh_offset(0, 0fx, 48fx);             // etOffset(0,0,48)
    sh_dist(0, 31.96fx);                 // etDist(32) + ANIM退位移 -4*0.01
    sh_xform(0, RISE_RAMP);
    loop {
        var off: int = ((rand(65536) - 32768) * 910) / 32768; // RANDF2 * 5deg，整波共用
        sh_angle(0, -90deg + (off as angle), 30deg);
        sh_fire(0);
        wait(15);
    }
}

// 源 BossCard8_ECir00：受击框24->r12，体碰16->r8，向下恒速0.8；drop*、ANM、
// flagSet/Clear(12)（出入相抵的屏外回收位）与无DPS外壳不可达的setDeath回调按口径省略。
async sub actor_main() {
    set_hurtbox(12fx);
    set_hitbox(8fx);
    move_vel(0, 90deg, 0.8fx, EASE_LINEAR);   // moveVel(pi/2, 0.8)
    loop { wait(1); }
}

// 源 BossCard8_at2：每10帧在 x=RANDF2*190、y=-32 生成一个 BossCard8_ECir00
async sub actor_rain() {
    loop {
        var u: fx = ((rand(65536) - 32768) as fx) / 32768;
        _ = spawn_enemy(u * 190fx, -32fx, 100, 0, 1000, 0, actor_main);
        wait(10);
    }
}

async sub boss_pattern() {
    // 源入口：%F0 = (%PLAYER_X2 > 0) ? 160 : -160；movePosTime(120, 4, %F0, 416)
    var tx: fx = -160fx;
    if $player_x > 0fx { tx = 160fx; }
    move_to(120, tx, 416fx, EASE_QUAD_OUT);
    wait(120);                           // 源 +120 时间标签
    spawn wave_emitter();                // @BossCard8_at() async
    spawn actor_rain();                  // @BossCard8_at2() async
    // BossCard8_1192/_1396：$C 递减循环，每次翻转 x，movePosTime(300,0,+,416)+wait(400)
    loop {
        tx = 0fx - tx;
        move_to(300, tx, 416fx, EASE_LINEAR);
        wait(400);
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hurtbox(20fx);                   // Boss init setHurtbox(40,40)
    set_hitbox(24fx);                    // Boss init setHitbox(48,48)
    // 源 spellEx(116, 5400) / setInterrupt(0,0,5400,"Boss9")
    spell_begin(0, SPELL_CARD8, boss_pattern, PHASE_FRAMES, 0, 0, 0);
    wait_spell();
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 2400, 0, 2400, 0, boss_main); // 源 lifeSet(2400)
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
